actions.script:
const number = (value) => value == null || value === '' ? null : Number(value)
const ids = chatAttachmentIds ? String(chatAttachmentIds).split(',').map((id) => id.trim()).filter((id) => id) : []
const records = heldByDeviceId || !body ? [] : ec.service.sync().name('org.moqui.comms.ChatScreenServices.lookup#Records')
        .parameters({operation: 'links', body: body || ''}).call().recordList || []
const out = ec.service.sync().name('org.moqui.chat.ChatScheduleServices.schedule#Message').parameters({chatRoomId: chatRoomId || '',
    body: body || null, replyToEventSeq: number(replyToEventSeq), threadRootEventSeq: number(threadRootEventSeq), chatAttachmentIdList: ids,
    recordList: records, sendDate: number(sendDate), heldByDeviceId: heldByDeviceId || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null}
        : {chatScheduledMessageId: out.chatScheduledMessageId, scheduled: out.scheduled})

const out = ec.service.sync().name('org.moqui.chat.ChatScheduleServices.update#ScheduledMessage').parameters({
    chatScheduledMessageId: chatScheduledMessageId || '', body: body != null && body !== '' ? body : null,
    sendDate: sendDate ? Number(sendDate) : null, deviceId: deviceId || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {scheduled: out.scheduled})

const out = ec.service.sync().name('org.moqui.chat.ChatScheduleServices.send#ScheduledMessageNow')
        .parameter('chatScheduledMessageId', chatScheduledMessageId || '').call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {eventSeq: out.eventSeq ?? null})

const out = ec.service.sync().name('org.moqui.chat.ChatScheduleServices.claim#HeldMessage').parameters({
    chatScheduledMessageId: chatScheduledMessageId || '', deviceId: deviceId || '', atOnce: atOnce === 'true' || atOnce === true}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null}
        : {claimed: !!out.claimed, sent: !!out.sent, clientRef: out.clientRef || null, reasonCode: out.reasonCode || null})

const out = ec.service.sync().name('org.moqui.chat.ChatScheduleServices.complete#HeldMessage').parameters({
    chatScheduledMessageId: chatScheduledMessageId || '', deviceId: deviceId || '', eventSeq: eventSeq ? Number(eventSeq) : null,
    draftLost: draftLost === 'true' || draftLost === true}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {sent: !!out.sent, sentLate: !!out.sentLate})

const out = ec.service.sync().name('org.moqui.chat.ChatScheduleServices.set#Reminder').parameters({chatRoomId: chatRoomId || '',
    eventSeq: eventSeq ? Number(eventSeq) : null, remindDate: remindDate ? Number(remindDate) : null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null}
        : {chatMessageReminderId: out.chatMessageReminderId, remindDate: out.remindDate})
